package com.renkio.game;
import android.app.*;import android.os.Bundle;import android.service.notification.StatusBarNotification;import com.google.android.gms.tasks.Tasks;import com.google.firebase.messaging.FirebaseMessaging;import java.io.File;import java.nio.file.Files;import java.nio.charset.StandardCharsets;import java.util.concurrent.TimeUnit;
/** Disposable-emulator end-to-end FCM delivery test. Never logs a device token. */
public final class PushSmoke  {
 public static void run(Instrumentation runner){Bundle result=new Bundle();try{if(android.os.Build.VERSION.SDK_INT>=33)runner.getUiAutomation().grantRuntimePermission(runner.getTargetContext().getPackageName(),android.Manifest.permission.POST_NOTIFICATIONS);runner.getTargetContext().getSharedPreferences("push",0).edit().putBoolean("enabled",true).putBoolean("audio",false).putBoolean("haptics",false).commit();FirebaseMessaging.getInstance().setAutoInitEnabled(true);String token=Tasks.await(FirebaseMessaging.getInstance().getToken(),60,TimeUnit.SECONDS);Files.write(new File(runner.getTargetContext().getFilesDir(),"push-test-token.txt").toPath(),token.getBytes(StandardCharsets.UTF_8));boolean delivered=false;long end=System.currentTimeMillis()+60000;NotificationManager manager=runner.getTargetContext().getSystemService(NotificationManager.class);while(System.currentTimeMillis()<end){for(StatusBarNotification n:manager.getActiveNotifications())if("Renkio bildirim testi".contentEquals(n.getNotification().extras.getCharSequence(Notification.EXTRA_TITLE,"")))delivered=true;if(delivered)break;Thread.sleep(500);}if(!delivered)throw new Exception("FCM notification did not arrive");result.putString("result","PASS: native FCM registration, background delivery, permission and notification rendering");runner.finish(Activity.RESULT_OK,result);}catch(Exception error){result.putString("error",error.getClass().getSimpleName()+": "+error.getMessage());runner.finish(Activity.RESULT_CANCELED,result);}}
}
